// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// LoginUser Вход
	// (POST /auth/login)
	LoginUser(ctx context.Context, request LoginUserRequestObject) (LoginUserResponseObject, error)
	// LogoutUser Выход
	// (POST /auth/logout)
	LogoutUser(ctx context.Context, request LogoutUserRequestObject) (LogoutUserResponseObject, error)
	// LogoutAllUserSessions Выход со всех устройств
	// (POST /auth/logout-all)
	LogoutAllUserSessions(ctx context.Context, request LogoutAllUserSessionsRequestObject) (LogoutAllUserSessionsResponseObject, error)
	// RefreshToken Обновление токенов
	// (POST /auth/refresh)
	RefreshToken(ctx context.Context, request RefreshTokenRequestObject) (RefreshTokenResponseObject, error)
	// RegisterUser Регистрация
	// (POST /auth/register)
	RegisterUser(ctx context.Context, request RegisterUserRequestObject) (RegisterUserResponseObject, error)
	// ListNotebooks Список блокнотов
	// (GET /notebooks)
	ListNotebooks(ctx context.Context, request ListNotebooksRequestObject) (ListNotebooksResponseObject, error)
	// CreateNotebook Создание блокнота
	// (POST /notebooks)
	CreateNotebook(ctx context.Context, request CreateNotebookRequestObject) (CreateNotebookResponseObject, error)
	// GetNotebook Блокнот
	// (GET /notebooks/{id})
	GetNotebook(ctx context.Context, request GetNotebookRequestObject) (GetNotebookResponseObject, error)
	// CreateCell Добавление блока
	// (POST /notebooks/{id}/cells)
	CreateCell(ctx context.Context, request CreateCellRequestObject) (CreateCellResponseObject, error)
	// DeleteCell Удаление блока
	// (DELETE /notebooks/{id}/cells/{index})
	DeleteCell(ctx context.Context, request DeleteCellRequestObject) (DeleteCellResponseObject, error)
	// GetNotebookContent Содержимое блокнота с хешем
	// (GET /notebooks/{id}/content)
	GetNotebookContent(ctx context.Context, request GetNotebookContentRequestObject) (GetNotebookContentResponseObject, error)
	// AddNotebookCell Добавление блока с проверкой хеша
	// (POST /notebooks/{id}/content/cells)
	AddNotebookCell(ctx context.Context, request AddNotebookCellRequestObject) (AddNotebookCellResponseObject, error)
	// RemoveNotebookCell Удаление блока с проверкой хеша
	// (DELETE /notebooks/{id}/content/cells/{cell_id})
	RemoveNotebookCell(ctx context.Context, request RemoveNotebookCellRequestObject) (RemoveNotebookCellResponseObject, error)
	// EditNotebookCell Редактирование блока с проверкой хеша
	// (PATCH /notebooks/{id}/content/cells/{cell_id})
	EditNotebookCell(ctx context.Context, request EditNotebookCellRequestObject) (EditNotebookCellResponseObject, error)
	// MoveNotebookCell Перемещение блока с проверкой хеша
	// (POST /notebooks/{id}/content/cells/{cell_id}/move)
	MoveNotebookCell(ctx context.Context, request MoveNotebookCellRequestObject) (MoveNotebookCellResponseObject, error)
	// GetCurrentUser Текущий пользователь
	// (GET /users/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// UpdateCurrentUser Сменить логин
	// (PATCH /users/me)
	UpdateCurrentUser(ctx context.Context, request UpdateCurrentUserRequestObject) (UpdateCurrentUserResponseObject, error)
	// UploadCurrentUserAvatar Загрузить или заменить аватар
	// (PUT /users/me/avatar)
	UploadCurrentUserAvatar(ctx context.Context, request UploadCurrentUserAvatarRequestObject) (UploadCurrentUserAvatarResponseObject, error)
	// ChangeCurrentUserPassword Сменить пароль
	// (PUT /users/me/password)
	ChangeCurrentUserPassword(ctx context.Context, request ChangeCurrentUserPasswordRequestObject) (ChangeCurrentUserPasswordResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

